mkdir -p /app/bin /app/out; cat > /app/bin/hourly.py <<'EOF'
import sys, os, re, json, math
from datetime import datetime, timedelta, timezone

CANON = ['temp', 'rh', 'pres', 'wspd', 'wdir', 'rain']
RANGE = {'temp': (-50, 60), 'rh': (0, 100), 'pres': (870, 1085),
         'wspd': (0, 60), 'wdir': (0, 360), 'rain': (0, 5000)}
EPOCH = datetime(1970, 1, 1)
DIR_RE = re.compile(r'^#\s*([a-z]+):(.*)$')


def convert(q, unit, v):
    if q == 'temp':
        if unit == 'degF': return (v - 32) * 5 / 9
        if unit == 'K': return v - 273.15
    elif q == 'rh':
        if unit == 'frac': return v * 100
    elif q == 'pres':
        if unit == 'kPa': return v * 10
        if unit == 'inHg': return v * 33.8638866667
        if unit == 'mmHg': return v * 1.33322387415
    elif q == 'wspd':
        if unit == 'kmh': return v / 3.6
        if unit == 'kn': return v * 1852 / 3600
        if unit == 'mph': return v * 0.44704
    elif q == 'rain':
        if unit.startswith('tips:'): return v * float(unit[5:])
    return v


def parse_time(s):
    s = s.strip().replace('T', ' ')
    d = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    return int((d - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s == 'Z':
        return 0
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return sign * (int(h) * 3600 + int(m) * 60)


def missing(f):
    f = f.strip()
    if f == '' or f == '---' or f.lower() == 'nan':
        return True
    if re.fullmatch(r'-9999(\.0*)?', f):
        return True
    return False


def read_file(path):
    with open(path, 'rb') as fh:
        text = fh.read().decode('utf-8-sig')
    hdr = {}
    cols = None
    units = {}
    rows = []   # (logger_utc, {q: val})
    syncs = []  # (logger_utc, ref)
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        if line.startswith('#'):
            m = DIR_RE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key in ('station', 'upload', 'interval', 'tz'):
                hdr[key] = val
            elif key == 'columns':
                cols = [c.strip() for c in val.split(',')]
            elif key == 'units':
                for p in val.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        units[a] = b
            elif key == 'sync':
                lg = ref = None
                for p in val.split():
                    if p.startswith('logger='):
                        lg = p[7:]
                    elif p.startswith('ref='):
                        ref = p[4:]
                if lg and ref:
                    tz = parse_tz(hdr.get('tz', 'Z'))
                    syncs.append((parse_time(lg) - tz,
                                  int((datetime.strptime(ref, '%Y-%m-%dT%H:%M:%SZ') - EPOCH).total_seconds())))
            continue
        tz = parse_tz(hdr.get('tz', 'Z'))
        fields = line.split(',')
        rec = {}
        t = None
        for c, f in zip(cols, fields):
            if c == 'time':
                t = parse_time(f) - tz
                continue
            if c not in RANGE or missing(f):
                continue
            try:
                v = float(f.strip())
                v = convert(c, units.get(c, ''), v)
            except ValueError:
                continue
            lo, hi = RANGE[c]
            if math.isfinite(v) and lo <= v <= hi:
                rec[c] = v
        rows.append((t, rec))
    return hdr, rows, syncs


def offset_at(t, pts):
    if not pts:
        return 0
    if t <= pts[0][0]:
        return pts[0][1]
    if t >= pts[-1][0]:
        return pts[-1][1]
    lo, hi = 0, len(pts) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if pts[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    t1, o1 = pts[lo]
    t2, o2 = pts[hi]
    if t == t1:
        return o1
    return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)


def r2(x):
    x = round(x + 0.0, 2)
    return 0.0 if x == 0 else x


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith('.log') or not os.path.isfile(p):
            continue
        hdr, rows, syncs = read_file(p)
        if 'station' not in hdr:
            continue
        up = int(hdr.get('upload', 0))
        st = stations.setdefault(hdr['station'], {'rows': {}, 'sync': {}, 'interval': None, 'iu': -1})
        if rows or st['interval'] is None:
            if up >= st['iu'] and 'interval' in hdr:
                st['interval'] = int(hdr['interval']); st['iu'] = up
        for t, rec in rows:
            old = st['rows'].get(t)
            if old is None or up > old[0]:
                st['rows'][t] = (up, rec)
        for t, ref in syncs:
            old = st['sync'].get(t)
            if old is None or up > old[0]:
                st['sync'][t] = (up, ref - t)
    out = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st['rows']:
            continue
        interval = st['interval']
        pts = sorted((t, o) for t, (u, o) in st['sync'].items())
        items = []
        for t, (u, rec) in st['rows'].items():
            items.append((t + offset_at(t, pts), t, rec))
        items.sort(key=lambda x: (x[0], x[1]))
        expected = 3600 / interval
        hours = {}
        def hk(c):
            return -((-c) // 3600) * 3600
        lastrain = None
        for c, t, rec in items:
            h = hk(c)
            d = hours.setdefault(h, {q: [] for q in CANON})
            for q in ('temp', 'rh', 'pres', 'wspd'):
                if q in rec:
                    d[q].append(rec[q])
            if 'wdir' in rec:
                d['wdir'].append((rec['wdir'], rec.get('wspd')))
            if 'rain' in rec:
                r = rec['rain']
                inc = None
                if lastrain is not None and (c - lastrain[0]) * 2 <= 5 * interval:
                    inc = r - lastrain[1] if r >= lastrain[1] else r
                lastrain = (c, r)
                d['rain'].append(inc)
        hs = sorted(hours)
        res = []
        h = hs[0]
        while h <= hs[-1]:
            d = hours.get(h)
            e = {'hour': (EPOCH + timedelta(seconds=h)).strftime('%Y-%m-%dT%H:%M:%SZ')}
            for q in CANON:
                vals = d[q] if d else []
                n = len(vals)
                v = None
                if n * 4 >= expected * 3 and n > 0:
                    if q in ('temp', 'rh', 'pres', 'wspd'):
                        v = r2(math.fsum(vals) / n)
                    elif q == 'wdir':
                        sx = sy = 0.0; k = 0
                        for a, s in vals:
                            if s is not None and s > 0:
                                sx += math.sin(math.radians(a)); sy += math.cos(math.radians(a)); k += 1
                        if k and (abs(sx) > 1e-9 or abs(sy) > 1e-9):
                            v = r2(math.degrees(math.atan2(sx, sy)) % 360)
                            if v >= 360: v = 0.0
                    else:
                        v = r2(math.fsum(i for i in vals if i is not None))
                e[q] = {'value': v, 'n': n}
            res.append(e)
            h += 3600
        out.append({'station': sid, 'interval_s': interval, 'hours': res})
    with open(outfile, 'w') as f:
        json.dump({'stations': out}, f)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
